46		private Clock clock;
47	
48		@BeforeEach
49		void setUp() {
50			properties = new GatewaySecurityProperties();
51			properties.getHmac().setEnabled(true);
52	
53			canonicalBuilder = new HmacCanonicalRequestBuilder();
54			clock = Clock.fixed(FIXED_TIME, ZoneOffset.UTC);
55		}
