57		private HmacAuthenticationManager manager() {
58			return new HmacAuthenticationManager(properties, canonicalBuilder,
59					nonceValidator, credentialResolver, clock);
60		}
61	
62		private AppCredential validCredential() {
63			return AppCredential.builder()
64					.appKey(APP_KEY)
65					.appSecret(APP_SECRET)
66					.appCode(APP_CODE)
67					.enabled(true)
68					.build();
69		}
