71		/**
72		 * Builds a valid HMAC signature for POST /api/data with the given inputs.
73		 */
74		private String sign(String timestamp, String nonce, byte[] bodyBytes) {
75			return sign("POST", "/api/data", timestamp, nonce, bodyBytes);
76		}
77	
78		private String sign(String method, String path, String timestamp, String nonce, byte[] bodyBytes) {
79			String bodyDigest = HmacAuthenticationManager.sha256Hex(bodyBytes);
80			String canonical = canonicalBuilder.build(APP_KEY, method, path,
81					null, timestamp, nonce, bodyDigest);
82			return HmacAuthenticationManager.hmacSha256Hex(APP_SECRET, canonical);
83		}
84	
85		private String validTimestamp() {
86			return String.valueOf(FIXED_TIME.toEpochMilli());
87		}
88	
89		private void stubNonceOk(String appKey, String nonce) {
90			when(nonceValidator.validate(eq(appKey), eq(nonce)))
91					.thenReturn(Mono.empty());
92		}
93	
94		private void stubCredentialOk() {
95			when(credentialResolver.resolve(eq(APP_KEY)))
96					.thenReturn(Mono.just(validCredential()));
97		}
